<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import WorkspaceSidebar from './WorkspaceSidebar.vue';
import {formatBytes} from './format-bytes';
import {validCloudDirectory} from './cloud-files-route';
type Item={id:string;path:string;size:string;sent:string;state:string;updated_at_utc:string;error:string;actual_path:string};
type Batch={id:string;target:string;created_at_utc:string;items?:Item[];total?:number;completed?:number;failed?:number;unknown?:number};
const names:Record<string,string>={receiving:'等待浏览器传入',queued:'等待上传',hashing:'计算分片校验',submitting:'准备远端上传',uploading:'上传分片',finalizing:'合并并核对',confirmed:'完成',failed:'失败',unknown:'结果待核对',cancelled:'已停止'};
const target=ref(new URLSearchParams(location.search).get('directory')||'/'),batches=ref<Batch[]>([]),batch=ref<Batch|null>(null),files=ref<File[]>([]),error=ref(''),busy=ref(false),auth=ref(false),transferred=ref(''),filter=ref(''),page=ref(0),ack=ref(false);
const priority:Record<string,number>={uploading:0,submitting:0,finalizing:0,hashing:0,unknown:1,failed:1,queued:2,receiving:3,confirmed:4,cancelled:5};
const visible=computed(()=>{const all=batch.value?.items||[];return all.filter(i=>!filter.value||i.state===filter.value).sort((a,b)=>priority[a.state]-priority[b.state]||a.path.localeCompare(b.path)).slice(page.value*100,(page.value+1)*100)}),matched=computed(()=>(batch.value?.items||[]).filter(i=>!filter.value||i.state===filter.value).length);
const completed=computed(()=>(batch.value?.items||[]).filter(i=>i.state==='confirmed').length);
let active=true,generation=0,controller:AbortController|undefined,xhr:XMLHttpRequest|undefined,timer:ReturnType<typeof setTimeout>|undefined;
function filename(file:File){return file.webkitRelativePath||file.name;}
function choose(event:Event){files.value=Array.from((event.target as HTMLInputElement).files||[]);ack.value=false;error.value='';}
function login(){auth.value=true;stop();location.assign('/login?next='+encodeURIComponent(location.pathname+location.search));}
async function request(url:string,init:RequestInit={}){const response=await fetch(url,{...init,credentials:'same-origin'});if(!active)throw Error('页面已离开，请到批次记录核对');if(response.status===401){login();throw Error('请重新登录')};if(!response.ok)throw Error(await response.text()||'上传请求失败');return response.json();}
function validBatch(value:any):value is Batch{return value&&/^[a-f0-9]{32}$/.test(value.id)&&validCloudDirectory(value.target)&&Array.isArray(value.items)&&value.items.length<=10000&&value.items.every((i:any)=>/^[a-f0-9]{32}$/.test(i.id)&&typeof i.path==='string'&&typeof i.size==='string'&&/^(0|[1-9][0-9]*)$/.test(i.size)&&typeof i.sent==='string'&&Object.hasOwn(names,i.state));}
async function load(id=batch.value?.id||''){
 if(!active||auth.value)return;clearTimeout(timer);const requestID=++generation;controller?.abort();controller=new AbortController();
 try{const response=await fetch(id?'/api/uploads/'+id:'/api/uploads',{credentials:'same-origin',signal:controller.signal});if(requestID!==generation||!active)return;if(response.status===401){login();return};if(!response.ok)throw Error(await response.text()||'上传记录不可读');const data=await response.json();if(requestID!==generation||!active)return;
 if(id){if(!validBatch(data)||data.id!==id)throw Error('上传批次响应无效');batch.value=data;target.value=data.target;}else{if(!Array.isArray(data.batches))throw Error('上传历史响应无效');batches.value=data.batches;}error.value='';
 }catch(e:any){if(requestID===generation&&active)error.value=e.message||'上传记录不可读'}finally{if(requestID===generation&&active&&!auth.value)timer=setTimeout(()=>load(id),2000)}
}
function open(id:string){if(busy.value)return;batch.value=null;page.value=0;filter.value='';files.value=[];history.pushState(null,'','/uploads?batch='+id);load(id);}
function send(item:Item,file:File,batchID:string){return new Promise<void>((resolve,reject)=>{xhr=new XMLHttpRequest();xhr.open('PUT','/api/uploads/'+batchID+'/'+item.id+'/content');xhr.withCredentials=true;xhr.upload.onprogress=event=>{if(active)transferred.value=filename(file)+' · 浏览器 → 本机 '+formatBytes(event.loaded)+' / '+formatBytes(file.size)};xhr.onload=()=>{if(xhr?.status===401){login();reject(Error('请重新登录'));return};if(xhr&&xhr.status>=200&&xhr.status<300)resolve();else reject(Error(xhr?.responseText||'本机暂存失败'))};xhr.onerror=()=>reject(Error('浏览器到本机的传输中断；已接收文件仍会在后台上传，缺失文件需重新选择'));xhr.onabort=()=>reject(Error('浏览器传输已停止'));xhr.send(file);});}
async function start(){
 if(busy.value||auth.value||!ack.value||!files.value.length)return;if(!validCloudDirectory(target.value)){error.value='请输入规范绝对网盘目录';return};busy.value=true;error.value='';
 try{let fixed=batch.value;if(!fixed){const manifest=files.value.map(file=>({path:filename(file),size:String(file.size)}));const value=await request('/api/uploads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({target:target.value,files:manifest})});if(!active)return;if(!validBatch(value)||value.target!==target.value||value.items?.length!==manifest.length||!value.items.every((item,index)=>item.path===manifest[index].path&&item.size===manifest[index].size))throw Error('上传清单响应与所选文件或目标不一致');fixed=value;batch.value=fixed;history.replaceState(null,'','/uploads?batch='+fixed.id)}
 const selected=new Map(files.value.map(file=>[filename(file),file]));for(const item of fixed.items||[]){if(!active)break;if(item.state!=='receiving')continue;const file=selected.get(item.path);if(!file||String(file.size)!==item.size)continue;await send(item,file,fixed.id)}if(active){transferred.value='本机接收已结束，后台上传进度见下方批次。';files.value=[];ack.value=false;await load(fixed.id)}
 }catch(e:any){if(active)error.value=e.message||'上传失败'}finally{busy.value=false;}
}
async function retry(){if(!batch.value||busy.value||auth.value)return;busy.value=true;const id=batch.value.id;try{await request('/api/uploads/'+id,{method:'POST'});await load(id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function cancel(){if(!batch.value||busy.value||auth.value)return;busy.value=true;const id=batch.value.id;try{await request('/api/uploads/'+id,{method:'DELETE'});await load(id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
function stop(){active=false;generation++;controller?.abort();clearTimeout(timer);xhr?.abort();}
function restore(event:PageTransitionEvent){if(event.persisted&&!auth.value){active=true;load(batch.value?.id||new URLSearchParams(location.search).get('batch')||'')}}
function pop(){if(busy.value)return;batch.value=null;page.value=0;load(new URLSearchParams(location.search).get('batch')||'')}
onMounted(()=>{document.title='上传任务 · NAS Downloader';window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);window.addEventListener('popstate',pop);const id=new URLSearchParams(location.search).get('batch')||'';if(id&&!/^[a-f0-9]{32}$/.test(id)){error.value='批次ID无效';return}load(id)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore);window.removeEventListener('popstate',pop)});
</script>
<template><div class="workspace event-workspace upload-workspace"><WorkspaceSidebar active="/uploads" @error="error=$event"/><main class="main"><header class="page-header"><div><p class="eyebrow">本机暂存 → 百度网盘</p><h1>上传任务</h1><p class="muted">批量选择文件或目录，先完整接收到本机，再后台分片上传。关闭页面后已接收的文件继续处理。</p></div><a class="button secondary" href="/cloud/files">返回网盘文件</a></header><p v-if="error" class="notice danger" role="alert">{{error}}</p><section v-if="!batch||batch.items?.some(item=>item.state==='receiving')" class="event-results"><h2>{{batch?'补传此批次缺失文件':'新建上传批次'}}</h2><label>目标网盘目录<input v-model="target" :disabled="busy||auth||!!batch"/></label><p v-if="batch">本批固定目标：{{batch.target}}</p><div class="upload-pickers"><label>选择多个文件<input type="file" multiple :disabled="busy||auth" @change="choose"/></label><label>选择目录<input type="file" webkitdirectory multiple :disabled="busy||auth" @change="choose"/></label></div><p class="muted">目录上传保留相对层级；浏览器目录选择不会提供空目录。文件会暂存在本机状态目录，需有足够磁盘空间。同名文件由百度另存名称，保留原文件；完成后以实际远端路径为准。</p><p>已选 {{files.length}} 个文件</p><label><input type="checkbox" v-model="ack" :disabled="busy||auth"/>已核对目标，确认将所选文件上传到该网盘目录</label><p><button class="button primary" data-testid="upload-start" :disabled="busy||auth||!ack||!files.length" @click="start">{{busy?'正在接收…':'接收并开始后台上传'}}</button><a v-if="batch" class="button secondary" href="/uploads">新建其他批次</a></p><p role="status">{{transferred}}</p></section><section v-if="batch" class="event-results"><header class="page-header"><h2>批次详情</h2><a class="button secondary" href="/uploads">新建上传批次</a><button class="button secondary" :disabled="busy||auth" @click="retry">重试明确失败的文件</button><button class="button secondary" :disabled="busy||auth" @click="cancel">停止尚未开始的文件</button></header><p class="muted">{{batch.id}} · 创建 UTC {{batch.created_at_utc}}</p><p>完成 {{completed}} / {{batch.items?.length}} · 远端提交结果待核对时，本批后续项暂停，不自动重发。</p><label>状态<select v-model="filter" @change="page=0"><option value="">全部</option><option v-for="(label,key) in names" :key="key" :value="key">{{label}}</option></select></label><div class="event-table-scroll"><table><thead><tr><th>文件 / 相对路径</th><th>大小</th><th>状态</th><th>已传分片</th><th>更新 UTC / 结果</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td>{{item.path}}</td><td :title="item.size+' B'">{{formatBytes(item.size)}}</td><td>{{names[item.state]}}</td><td>{{formatBytes(item.sent)}}</td><td>{{item.updated_at_utc}}<br>{{item.error||item.actual_path}}</td></tr></tbody></table></div><p>匹配 {{matched}} 项 · 第 {{page+1}} 页</p><button class="button secondary" :disabled="page===0" @click="page--">上一页</button><button class="button secondary" :disabled="(page+1)*100>=matched" @click="page++">下一页</button></section><section v-else class="event-results"><h2>最近上传批次（最多50批）</h2><div class="event-table-scroll"><table><thead><tr><th>批次</th><th>目标目录</th><th>完成 / 总数</th><th>异常</th><th>创建 UTC</th><th>操作</th></tr></thead><tbody><tr v-for="row in batches" :key="row.id"><td>{{row.id}}</td><td>{{row.target}}</td><td>{{row.completed}} / {{row.total}}</td><td>失败 {{row.failed}} · 待核对 {{row.unknown}}</td><td>{{row.created_at_utc}}</td><td><button class="button secondary" :disabled="busy" @click="open(row.id)">查看批次</button></td></tr></tbody></table></div></section></main></div></template>
<style scoped>.upload-workspace input:not([type=checkbox]),.upload-workspace select{border:1px solid #dce2ed;border-radius:6px;padding:8px;max-width:100%}.upload-pickers{display:flex;flex-wrap:wrap;gap:16px;margin:16px 0}.upload-pickers label{display:grid;gap:8px}.upload-workspace :deep(th){width:auto}.upload-workspace td{white-space:normal;overflow-wrap:anywhere;max-width:400px}</style>
